CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, address TEXT COLLATE NOCASE UNIQUE NOT NULL, ensName TEXT, baseName TEXT, displayName TEXT NOT NULL, farcasterHandle TEXT, joinedAt TEXT NOT NULL, bio TEXT);
CREATE TABLE jobs (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, budget TEXT NOT NULL, "desc" TEXT NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE services (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, rate TEXT NOT NULL, "desc" TEXT NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE skills (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, createdAt TEXT NOT NULL, userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE, UNIQUE(userId,name));
CREATE TABLE endorsements (id TEXT PRIMARY KEY NOT NULL, createdAt TEXT NOT NULL, skillId TEXT NOT NULL REFERENCES skills(id) ON DELETE CASCADE ON UPDATE CASCADE, endorserId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE, UNIQUE(skillId,endorserId));
CREATE TABLE chat_rooms (id TEXT PRIMARY KEY NOT NULL, type TEXT NOT NULL, title TEXT, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, jobId TEXT REFERENCES jobs(id) ON DELETE CASCADE ON UPDATE CASCADE, serviceId TEXT REFERENCES services(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE chat_participants (id TEXT PRIMARY KEY NOT NULL, joinedAt TEXT NOT NULL, chatRoomId TEXT NOT NULL REFERENCES chat_rooms(id) ON DELETE CASCADE ON UPDATE CASCADE, userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE, UNIQUE(chatRoomId,userId));
CREATE TABLE chat_messages (id TEXT PRIMARY KEY NOT NULL, content TEXT NOT NULL, xmtpId TEXT, createdAt TEXT NOT NULL, chatRoomId TEXT NOT NULL REFERENCES chat_rooms(id) ON DELETE CASCADE ON UPDATE CASCADE, senderId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX jobs_created ON jobs(createdAt);
CREATE INDEX services_created ON services(createdAt);
CREATE INDEX participants_user ON chat_participants(userId);
CREATE INDEX messages_room_created ON chat_messages(chatRoomId,createdAt);
CREATE TABLE auth_challenges (nonce TEXT PRIMARY KEY NOT NULL, browserHash TEXT NOT NULL, expiresAt INTEGER NOT NULL, consumedAt INTEGER);
CREATE INDEX challenges_expiration ON auth_challenges(expiresAt);
